// <<< words
const shapes = new Map(), baked = new Map();
function word(name) {
  // The demo i18n script also sets this attribute. Read it at the start of each effect.
  const locale = document.documentElement.lang.toLowerCase();
  const requested = locale === 'zh-cn' ? 'zh-CN' : locale;
  const lang = Object.hasOwn(WORDS, requested) && Object.hasOwn(WORDS[requested], name) ? requested : 'ja';
  if (!Object.hasOwn(WORDS[lang], name)) return;
  const key = `${lang}/${name}`;
  if (!shapes.has(key)) {
    const [w, h, path] = WORDS[lang][name];
    shapes.set(key, { key, w, h, p: new Path2D(path) });
  }
  return shapes.get(key);
}
// Cache each localized shape and style so a word on screen costs one drawImage a frame.
function bake(s, fc, oc, dots) {
  const key = JSON.stringify([s.key, fc, oc, dots]); let c = baked.get(key); if (c) return c;
  const unit = s.w / 520, pad = Math.ceil(24 * unit), e = s.w * 0.035;
  c = document.createElement('canvas'); c.width = s.w + pad * 2; c.height = s.h + pad * 2;
  const x = c.getContext('2d'); x.translate(pad, pad); x.lineJoin = 'round';
  x.strokeStyle = x.fillStyle = oc; x.lineWidth = e * 2; x.stroke(s.p); x.fill(s.p);
  if (dots) {   // screentone letters: dots in the outline colour on white
    const t = document.createElement('canvas'); t.width = 22; t.height = 44; const y = t.getContext('2d'); y.fillStyle = '#fff'; y.fillRect(0, 0, 22, 44); y.fillStyle = oc; y.beginPath();
    for (const [px, py] of [[0, 0], [22, 0], [0, 44], [22, 44], [11, 22]]) { y.moveTo(px + 5.2, py); y.arc(px, py, 5.2, 0, TAU); } y.fill();
    const pattern = x.createPattern(t, 'repeat');
    if (unit !== 1) pattern.setTransform(new DOMMatrix().scaleSelf(unit));
    x.fillStyle = pattern;
  } else x.fillStyle = fc;
  x.fill(s.p); baked.set(key, c); return c;
}
